"""Apply reviewed chapter 9 subject edits to a supplied content/ch09 directory."""
from argparse import ArgumentParser
from pathlib import Path

parser = ArgumentParser()
parser.add_argument('chapter', type=Path)
args = parser.parse_args()
files = {}

def change(file, old, new, n=1):
    source = files.get(file, (args.chapter / file).read_text())
    if source.count(old) != n:
        raise RuntimeError(f'{file}: expected {n} occurrence(s) of {old!r}')
    files[file] = source.replace(old,new)

def paragraph(file, prefix, new):
    source = files.get(file, (args.chapter / file).read_text())
    matches = [line for line in source.splitlines() if line.startswith(prefix)]
    if len(matches) != 1:
        raise RuntimeError(f'{file}: expected one paragraph starting with {prefix!r}')
    change(file, matches[0], new)

